//! Replays the fixtures in `tests/fixtures/parity/` (generated by running
//! the real TypeScript reference under `bun` — see the README there) through
//! this crate's Rust ports and asserts bit-for-bit (float epsilon) parity.

use std::collections::BTreeMap;

use aphrody_rag_core::{
    ChunkOptions, Chunker, MarkdownChunker, ProseChunker,
    eval::{
        GoldCase, RetrievedHit, aggregate, aggregate_by_tag, matches_expected_url, normalize_url,
        run_case,
    },
};
use serde::Deserialize;
use serde_json::Value;

const EVAL_GOLDEN: &str = include_str!("fixtures/parity/eval_golden.json");
const CHUNK_GOLDEN: &str = include_str!("fixtures/parity/prose_chunk_golden.json");
const UNICODE_GOLDEN: &str = include_str!("fixtures/parity/unicode_length_golden.json");

#[derive(Deserialize)]
struct EvalGolden {
    #[serde(rename = "normalizeUrl")]
    normalize_url: BTreeMap<String, String>,
    #[serde(rename = "matchesExpectedUrl")]
    matches_expected_url: BTreeMap<String, bool>,
    overall: Value,
    #[serde(rename = "byTag")]
    by_tag: BTreeMap<String, Value>,
}

fn hit(rowid: i64, title: &str, url: &str, snippet: &str, score: f64) -> RetrievedHit {
    RetrievedHit {
        rowid: Some(rowid),
        title: title.to_string(),
        url: url.to_string(),
        snippet: snippet.to_string(),
        score,
        ..Default::default()
    }
}

fn hits_for(q: &str) -> Vec<RetrievedHit> {
    match q {
        "who is freezer" => vec![
            hit(1, "Goku", "/wiki/goku", "hero", 0.5),
            hit(2, "Freezer", "/wiki/freezer", "tyrant", 0.9),
        ],
        "freezer forms" => vec![
            hit(3, "Freezer", "/wiki/freezer", "form 1", 0.9),
            hit(4, "Freezer Hell", "/wiki/freezer-hell", "final form", 0.8),
        ],
        "zeni currency" => {
            vec![hit(
                5,
                "Currency",
                "/wiki/monnaie",
                "The zeni is used on Earth.",
                0.7,
            )]
        }
        "kamehameha" => vec![
            hit(6, "Goku", "/wiki/goku", "uses techniques", 0.4),
            hit(7, "Kamehameha", "/wiki/kamehameha", "signature move", 0.85),
        ],
        "vegeta prince" => vec![],
        other => panic!("unexpected query in golden fixture: {other}"),
    }
}

fn cases() -> Vec<GoldCase> {
    vec![
        GoldCase {
            q: "who is freezer".into(),
            expect_url: vec!["/wiki/freezer".into()],
            ..Default::default()
        },
        GoldCase {
            q: "freezer forms".into(),
            expect_url: vec!["/wiki/freezer".into(), "/wiki/freezer-hell".into()],
            ..Default::default()
        },
        GoldCase {
            q: "zeni currency".into(),
            expect: vec!["zeni".into()],
            ..Default::default()
        },
        GoldCase {
            q: "kamehameha".into(),
            expect_url: vec!["/wiki/kamehameha".into()],
            tags: vec!["technique".into()],
            ..Default::default()
        },
        GoldCase {
            q: "vegeta prince".into(),
            expect_url: vec!["/wiki/vegeta".into()],
            tags: vec!["character".into(), "saiyan".into()],
            ..Default::default()
        },
    ]
}

fn approx(a: f64, b: f64) -> bool {
    (a - b).abs() < 1e-9
}

#[test]
fn eval_matches_bun_generated_golden() {
    let golden: EvalGolden = serde_json::from_str(EVAL_GOLDEN).expect("parse eval_golden.json");

    assert_eq!(
        normalize_url("https://www.example.com/wiki/Freezer/"),
        golden.normalize_url["https://www.example.com/wiki/Freezer/"]
    );
    assert_eq!(
        normalize_url("/wiki/Freezer/?x=1"),
        golden.normalize_url["/wiki/Freezer/?x=1"]
    );

    assert_eq!(
        matches_expected_url("/wiki/freezer-futur", "/wiki/freezer"),
        golden.matches_expected_url["freezer-futur_vs_freezer"]
    );
    assert_eq!(
        matches_expected_url("/wiki/freezer", "/wiki/freezer"),
        golden.matches_expected_url["freezer_vs_freezer"]
    );

    let results: Vec<_> = cases()
        .into_iter()
        .map(|c| {
            let h = hits_for(&c.q);
            run_case(c, &h, "lexical", 0)
        })
        .collect();
    let overall = aggregate(&results);

    assert_eq!(
        overall.cases,
        golden.overall["cases"].as_u64().unwrap() as usize
    );
    for &k in &aphrody_rag_core::eval::RANKS {
        let expected = golden.overall["recall"][k.to_string()].as_f64().unwrap();
        assert!(
            approx(overall.recall[&k], expected),
            "recall@{k}: {} vs {expected}",
            overall.recall[&k]
        );
    }
    assert!(approx(overall.mrr, golden.overall["mrr"].as_f64().unwrap()));
    assert!(approx(
        overall.ndcg,
        golden.overall["ndcg"].as_f64().unwrap()
    ));

    let by_tag = aggregate_by_tag(&results);
    for (ts_tag, expected) in &golden.by_tag {
        // The Rust port renames the TS default group "sans-tag" to "untagged".
        let rust_tag = if ts_tag == "sans-tag" {
            "untagged"
        } else {
            ts_tag.as_str()
        };
        let actual = &by_tag[rust_tag];
        assert_eq!(
            actual.cases,
            expected["cases"].as_u64().unwrap() as usize,
            "tag {rust_tag}"
        );
        assert!(
            approx(actual.mrr, expected["mrr"].as_f64().unwrap()),
            "tag {rust_tag} mrr"
        );
        assert!(
            approx(actual.ndcg, expected["ndcg"].as_f64().unwrap()),
            "tag {rust_tag} ndcg"
        );
    }
}

#[derive(Deserialize)]
struct ChunkGolden {
    #[serde(rename = "maxChunkChars")]
    max_chunk_chars: usize,
    #[serde(rename = "overlapPct")]
    overlap_pct: f32,
    doc: String,
    chunks: Vec<TsChunk>,
}

#[derive(Deserialize)]
struct TsChunk {
    content: String,
}

#[test]
fn markdown_chunker_matches_bun_generated_chunk_document_golden() {
    let golden: ChunkGolden =
        serde_json::from_str(CHUNK_GOLDEN).expect("parse prose_chunk_golden.json");
    let opts = ChunkOptions {
        max_chars: golden.max_chunk_chars,
        overlap_pct: golden.overlap_pct,
        ..ChunkOptions::ts_parity()
    };
    let chunker = MarkdownChunker;
    let chunks = chunker.chunk("doc.md", &golden.doc, &opts);

    let actual_texts: Vec<&str> = chunks.iter().map(|c| c.text.as_str()).collect();
    let expected_texts: Vec<&str> = golden.chunks.iter().map(|c| c.content.as_str()).collect();
    assert_eq!(actual_texts, expected_texts);
}

// --- Unicode length-unit parity (correction 1): French accents + Japanese --

#[derive(Deserialize)]
struct UnicodeGolden {
    #[serde(rename = "maxChunkChars")]
    max_chunk_chars: usize,
    #[serde(rename = "overlapPct")]
    overlap_pct: f32,
    fr: UnicodeLang,
    ja: UnicodeLang,
}

#[derive(Deserialize)]
struct UnicodeLang {
    text: String,
    #[serde(rename = "lengthUtf16")]
    length_utf16: usize,
    chunks: Vec<TsChunk>,
}

/// French accented paragraph (>3000 UTF-16 units): each accented letter is 2
/// UTF-8 bytes but 1 UTF-16 unit, so byte-sizing would have cut chunks ~10%
/// too early. Under `ts_parity()` (`LengthUnit::Utf16`), the real
/// `chunkDocument` produced 3 chunks — verified with `bun` on 2026-09-19 (see
/// `tests/fixtures/parity/README.md`).
#[test]
fn prose_chunker_matches_bun_golden_for_french_accents_under_utf16() {
    let golden: UnicodeGolden =
        serde_json::from_str(UNICODE_GOLDEN).expect("parse unicode_length_golden.json");
    assert_eq!(
        aphrody_rag_core::text::measure(&golden.fr.text, aphrody_rag_core::LengthUnit::Utf16),
        golden.fr.length_utf16
    );

    let opts = ChunkOptions {
        max_chars: golden.max_chunk_chars,
        overlap_pct: golden.overlap_pct,
        ..ChunkOptions::ts_parity()
    };
    let chunks = ProseChunker.chunk("fr.txt", &golden.fr.text, &opts);
    assert_eq!(
        chunks.len(),
        golden.fr.chunks.len(),
        "chunk count must match the real chunkDocument run"
    );
    let actual: Vec<&str> = chunks.iter().map(|c| c.text.as_str()).collect();
    let expected: Vec<&str> = golden
        .fr
        .chunks
        .iter()
        .map(|c| c.content.as_str())
        .collect();
    assert_eq!(actual, expected);
}

/// Japanese paragraph (>5000 UTF-16 units, only `。` terminators, no ASCII
/// punctuation): under `ts_parity()` (no CJK sentence breaks — matching
/// upstream, which has none), `chunkDocument` cannot split it at all and
/// emits exactly 1 oversized chunk — verified with `bun` on 2026-09-19. This
/// is the "before" half of correction 2's before/after test in
/// `chunk_invariants.rs`.
#[test]
fn prose_chunker_matches_bun_golden_for_japanese_under_parity_single_chunk() {
    let golden: UnicodeGolden =
        serde_json::from_str(UNICODE_GOLDEN).expect("parse unicode_length_golden.json");
    assert_eq!(
        aphrody_rag_core::text::measure(&golden.ja.text, aphrody_rag_core::LengthUnit::Utf16),
        golden.ja.length_utf16
    );

    let opts = ChunkOptions {
        max_chars: golden.max_chunk_chars,
        overlap_pct: golden.overlap_pct,
        ..ChunkOptions::ts_parity()
    };
    let chunks = ProseChunker.chunk("ja.txt", &golden.ja.text, &opts);
    assert_eq!(
        chunks.len(),
        1,
        "ts_parity has no CJK support: the whole paragraph is one unsplittable sentence"
    );
    assert_eq!(golden.ja.chunks.len(), 1);
    assert_eq!(chunks[0].text, golden.ja.chunks[0].content);
}

/// Correction 2's before/after: the exact same Japanese paragraph (only `。`
/// terminators, no ASCII punctuation) that `ts_parity()` cannot split
/// (previous test: 1 oversized chunk) DOES split correctly under aphrody's
/// own default `ChunkOptions` (`cjk_sentence_breaks: true`), producing
/// multiple chunks all within `max_chars` (measured in `Utf16` units, the
/// default `length_unit`).
#[test]
fn prose_chunker_default_options_split_japanese_without_ascii_punctuation() {
    let golden: UnicodeGolden =
        serde_json::from_str(UNICODE_GOLDEN).expect("parse unicode_length_golden.json");

    let before_opts = ChunkOptions {
        max_chars: golden.max_chunk_chars,
        overlap_pct: golden.overlap_pct,
        ..ChunkOptions::ts_parity()
    };
    let before = ProseChunker.chunk("ja.txt", &golden.ja.text, &before_opts);

    let after_opts = ChunkOptions {
        max_chars: golden.max_chunk_chars,
        overlap_pct: golden.overlap_pct,
        ..ChunkOptions::default()
    };
    let after = ProseChunker.chunk("ja.txt", &golden.ja.text, &after_opts);

    eprintln!(
        "correction 2 before/after — ts_parity: {} chunk(s) (max {} units); aphrody default: \
         {} chunk(s), all <= {} units",
        before.len(),
        before
            .iter()
            .map(|c| aphrody_rag_core::text::measure(&c.text, aphrody_rag_core::LengthUnit::Utf16))
            .max()
            .unwrap_or(0),
        after.len(),
        after_opts.max_chars,
    );

    assert_eq!(
        before.len(),
        1,
        "before: parity mode still can't split CJK-only prose"
    );
    assert!(before.iter().any(|c| aphrody_rag_core::text::measure(
        &c.text,
        aphrody_rag_core::LengthUnit::Utf16
    ) > before_opts.max_chars));

    assert!(
        after.len() > 1,
        "after: the default cjk_sentence_breaks must split this paragraph"
    );
    for c in &after {
        let len = aphrody_rag_core::text::measure(&c.text, aphrody_rag_core::LengthUnit::Utf16);
        assert!(
            len <= after_opts.max_chars,
            "chunk {:?} measured {len} units > max_chars {}",
            c.symbol,
            after_opts.max_chars
        );
    }
}
